"use client";

/* oxlint-disable anti-slop/no-runtime-typeof, anti-slop/no-unknown-parameters, anti-slop/no-unknown-returns, eslint/complexity, promise/avoid-new, promise/prefer-await-to-callbacks, typescript/promise-function-async, eslint/require-await, typescript/no-unnecessary-type-parameters -- The component probes host and browser capabilities at run time. The cache stores values of every query family, so its data and errors are unknown until a query function parses them, and the useAssetImage and useGeneratedImageSource ports keep the component branches. Timers and FileReader have no promise form, and the promise-function-async, require-await and return-await rules contradict each other for functions that hand back a shared promise. */

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useInsertionEffect,
  useRef,
  useState,
  useSyncExternalStore,
} from "react";

/** Resolves asset pointers, host file paths and plain image URLs with a shared cache. */

const IMAGE_CACHE_TTL_MS = 4 * 60 * 1000;
const MAX_RETRIES = 4;
const MAX_RETRY_DELAY = 24_000;

/** The id of the host on this machine. */
export const LOCAL_HOST_ID = "local";

/** The host id of a durable (cloud) task. */
const DURABLE_HOST_ID = "durable";

const FILE_SERVICE_SCHEME = "file-service://";
const SEDIMENT_SCHEME = "sediment://";

/* ------------------------------------------------------ classification --- */

interface RegisteredAssetFile {
  download_url?: string;
  file_name?: string | null;
  mime_type?: string | null;
  url: string;
}

/** Registered asset files by owner (sandbox and tool assets). */
const registeredAssetOwners = new Map<
  string,
  Record<string, RegisteredAssetFile>
>();

/** Registers the files an owner (for example a tool result) makes available by URL. */
export const registerImageAssetFiles = (
  owner: string,
  files: Record<string, RegisteredAssetFile>
): (() => void) => {
  registeredAssetOwners.set(owner, files);

  return () => {
    if (registeredAssetOwners.get(owner) === files) {
      registeredAssetOwners.delete(owner);
    }
  };
};

/** The registered file for a URL (the query string is ignored). */
const registeredAssetFile = (src: string): RegisteredAssetFile | undefined => {
  const withoutQuery = src.replace(/\?.*$/u, "");

  for (const files of registeredAssetOwners.values()) {
    const file = files[withoutQuery];

    if (file !== undefined) {
      return file;
    }
  }

  return undefined;
};

/** Does this source go through the asset resolver? */
export const isAssetUrl = (src: string): boolean =>
  src.startsWith(FILE_SERVICE_SCHEME) ||
  src.startsWith(SEDIMENT_SCHEME) ||
  registeredAssetFile(src) !== undefined;

/** The id the resolver is asked for. */
export const assetPointerFileId = (src: string): string => {
  if (src.startsWith(FILE_SERVICE_SCHEME)) {
    return src.replace(FILE_SERVICE_SCHEME, "");
  }

  return src.startsWith(SEDIMENT_SCHEME)
    ? src.replace(SEDIMENT_SCHEME, "")
    : src;
};

const LOCAL_PATH_START = /^(?:[\\/]|[A-Za-z]:[\\/])/u;
const DRIVE_PATH = /^[A-Za-z]:[\\/]/u;
const UNC_BACKSLASH_PATH = /^\\\\[^\\]+\\[^\\]+/u;
const UNC_SLASH_PATH = /^\/\/[^/]+\/[^/]+/u;
const DRIVE_AFTER_SLASH = /^\/[A-Za-z]:[\\/]/u;

/** Backslashes to slashes. */
const toForwardSlashes = (path: string) => path.replaceAll("\\", "/");

/** A POSIX, drive or UNC absolute path. */
const isAbsolutePath = (path: string) =>
  (path.startsWith("/") && !path.startsWith("//")) ||
  DRIVE_PATH.test(path) ||
  UNC_BACKSLASH_PATH.test(path) ||
  UNC_SLASH_PATH.test(path);

/** The absolute local path a source names, or null. */
export const localFilePath = (
  src: string | null | undefined
): string | null => {
  if (src === null || src === undefined) {
    return null;
  }

  const trimmed = src.trim();

  if (trimmed.length === 0 || !LOCAL_PATH_START.test(trimmed)) {
    return null;
  }

  const normalized = toForwardSlashes(trimmed);

  if (!isAbsolutePath(normalized)) {
    return null;
  }

  const keepsOriginal =
    trimmed.startsWith("/") &&
    !normalized.startsWith("//") &&
    !DRIVE_AFTER_SLASH.test(trimmed);

  return keepsOriginal ? trimmed : normalized;
};

/** The in-app file URL of a local path. */
export const localFileUrl = (path: string): string => {
  const slashed = toForwardSlashes(path);
  const rooted = DRIVE_PATH.test(slashed) ? `/${slashed}` : slashed;

  return `app://fs/@fs${encodeURI(rooted).replaceAll("#", "%23").replaceAll("?", "%3F")}`;
};

const MIME_TYPES = new Map([
  [".avif", "image/avif"],
  [".gif", "image/gif"],
  [".jpeg", "image/jpeg"],
  [".jpg", "image/jpeg"],
  [".png", "image/png"],
  [".svg", "image/svg+xml"],
  [".webp", "image/webp"],
]);

/** The MIME type from the file extension. */
const mimeTypeOf = (path: string): string => {
  const name = path.split(/[\\/]/u).at(-1) ?? "";
  const dot = name.lastIndexOf(".");
  const extension = dot > 0 ? name.slice(dot).toLowerCase() : "";

  return MIME_TYPES.get(extension) ?? "application/octet-stream";
};

/* ------------------------------------------------------------- host --- */

export interface LocalFileRequest {
  conversationId?: string | null;
  environmentId?: string;
  hostId: string;
  path: string;
}

export interface ImageSourceHost {
  /** The host and environment a conversation runs in, or null. */
  conversationEnvironment: (
    conversationId: string
  ) => { environmentId?: string; hostId: string } | null;
  /** The host a conversation runs on, or null. */
  conversationHostId: (conversationId: string) => string | null;
  /** The kind of a host. */
  hostKind: (hostId: string) => { id: string; kind: "local" | "remote" };
  /** Reads a file through the host; null when the host cannot. */
  readBinary:
    | ((
        request: LocalFileRequest,
        signal: AbortSignal
      ) => Promise<{ contentsBase64: string }>)
    | null;
}

/** No conversation, every host is the local one, no file reads. */
const DEFAULT_HOST: ImageSourceHost = {
  conversationEnvironment: () => null,
  conversationHostId: () => null,
  hostKind: () => ({ id: LOCAL_HOST_ID, kind: "local" }),
  readBinary: null,
};

export const ImageSourceHostContext =
  createContext<ImageSourceHost>(DEFAULT_HOST);

/* ---------------------------------------------------------- resolver --- */

export type ImageAssetResolution =
  | {
      downloadUrl: string;
      kind: "available";
      requestHeaders?: Record<string, string>;
    }
  | { kind: "permanently-deleted" }
  | { kind: "trashed"; libraryFileId: string };

export type ImageCheckResult = "available" | "deleted" | "error";

export interface ImageAssetResolver {
  /** The cache scope; the default is ["images"]. */
  cacheKey?: readonly string[];
  /** Records the check outcome of a validation session. */
  imageLoading?: object;
  resolveAsset: (fileId: string) => Promise<ImageAssetResolution>;
  showCachedImageDuringValidation?: boolean;
  /** Use the resolved URL as the image source instead of downloading it. */
  useDownloadUrlAsImageSrc?: boolean;
  validationSessionId?: string;
}

export interface ImageLoadTiming {
  resourceTiming?: {
    decoded_body_size: number;
    encoded_body_size: number;
    initiator_type: string;
    resource_duration_ms: number;
    transfer_size: number;
  };
  startedAt: number;
}

export interface DeletedImageState {
  libraryFileId?: string;
  status: "permanently-deleted" | "trashed";
}

type AssetQueryData =
  | {
      blob: Blob;
      dataUrl: string;
      downloadUrl: string;
      kind: "download";
      loadTiming: ImageLoadTiming;
      objectUrl: string | null;
    }
  | { kind: "deleted"; state: DeletedImageState }
  | { kind: "url"; url: string };

/** The types that get an object URL. */
const OBJECT_URL_TYPES = new Set([
  "image/avif",
  "image/bmp",
  "image/gif",
  "image/jpeg",
  "image/jpg",
  "image/png",
  "image/vnd.microsoft.icon",
  "image/webp",
  "image/x-icon",
  "image/x-png",
]);

/** The blob behind an object URL this module made. */
const objectUrlBlobs = new Map<string, Blob>();

export const blobForObjectUrl = (url: string): Blob | undefined =>
  objectUrlBlobs.get(url);

/** Thrown when the caller stopped caring about a result. */
class CancelledError extends Error {
  constructor() {
    super("Image request cancelled");
    this.name = "CancelledError";
  }
}

/* ------------------------------------------------------- query store --- */

type QueryStatus = "error" | "pending" | "success";

interface QueryState {
  data: unknown;
  dataUpdateCount: number;
  error: unknown;
  errorUpdatedAt: number;
  fetchStatus: "fetching" | "idle";
  invalidated: boolean;
  status: QueryStatus;
}

interface QueryRunOptions {
  fn: (context: {
    key: readonly unknown[];
    signal: AbortSignal;
  }) => Promise<unknown>;
  gcTime: number;
  staleTime: number;
}

interface QueryRecord {
  controller: AbortController | null;
  gcTimer: ReturnType<typeof setTimeout> | undefined;
  hash: string;
  key: readonly unknown[];
  listeners: Set<() => void>;
  /** The update count when the first observer subscribed (isFetchedAfterMount). */
  mountedAt: number;
  observers: number;
  options: QueryRunOptions | null;
  promise: Promise<unknown> | null;
  state: QueryState;
  updatedAt: number;
}

const INITIAL_STATE: QueryState = {
  data: undefined,
  dataUpdateCount: 0,
  error: null,
  errorUpdatedAt: 0,
  fetchStatus: "idle",
  invalidated: false,
  status: "pending",
};

/** Object keys are sorted so equal keys hash equally. */
const hashKey = (key: readonly unknown[]): string =>
  JSON.stringify(key, (_name, value: unknown) =>
    typeof value === "object" && value !== null && !Array.isArray(value)
      ? Object.fromEntries(
          Object.entries(value).toSorted(([first], [second]) =>
            first.localeCompare(second)
          )
        )
      : value
  );

/**
 * Each query key family stores one data type, written only by its own query
 * function, so reading it back as that type is sound.
 */
const dataOf = <Data>(data: unknown): Data | undefined =>
  // SAFETY: the query function of the key family wrote this value with this type.
  // oxlint-disable-next-line typescript/no-unsafe-type-assertion
  data as Data | undefined;

const records = new Map<string, QueryRecord>();

const removalListeners = new Set<(record: QueryRecord) => void>();
const updateListeners = new Set<(record: QueryRecord) => void>();

const recordFor = (key: readonly unknown[]): QueryRecord => {
  const hash = hashKey(key);
  const existing = records.get(hash);

  if (existing !== undefined) {
    return existing;
  }

  const created: QueryRecord = {
    controller: null,
    gcTimer: undefined,
    hash,
    key,
    listeners: new Set(),
    mountedAt: 0,
    observers: 0,
    options: null,
    promise: null,
    state: INITIAL_STATE,
    updatedAt: 0,
  };

  records.set(hash, created);

  return created;
};

const patchState = (record: QueryRecord, patch: Partial<QueryState>) => {
  record.state = { ...record.state, ...patch };

  for (const listener of record.listeners) {
    listener();
  }

  for (const listener of updateListeners) {
    listener(record);
  }
};

const scheduleGc = (record: QueryRecord, gcTime: number) => {
  clearTimeout(record.gcTimer);

  if (record.observers > 0 || !Number.isFinite(gcTime)) {
    return;
  }

  record.gcTimer = setTimeout(() => {
    if (record.observers === 0 && records.get(record.hash) === record) {
      records.delete(record.hash);

      for (const listener of removalListeners) {
        listener(record);
      }
    }
  }, gcTime);
};

/** Retry network and server failures up to four times. */
const shouldRetry = (failureCount: number, error: unknown): boolean => {
  if (failureCount >= MAX_RETRIES) {
    return false;
  }

  const status =
    typeof error === "object" &&
    error !== null &&
    "status" in error &&
    typeof error.status === "number"
      ? error.status
      : null;

  return (
    status === null ||
    status === 408 ||
    status === 425 ||
    status === 429 ||
    (status >= 500 && status <= 599)
  );
};

const wait = (milliseconds: number, signal: AbortSignal) =>
  new Promise<void>((resolve, reject) => {
    const timer = setTimeout(resolve, milliseconds);

    signal.addEventListener(
      "abort",
      () => {
        clearTimeout(timer);
        reject(new DOMException("The wait was cancelled", "AbortError"));
      },
      { once: true }
    );
  });

const isFresh = (record: QueryRecord, staleTime: number) =>
  record.state.status === "success" &&
  !record.state.invalidated &&
  performance.now() - record.updatedAt < staleTime;

const runQuery = (
  record: QueryRecord,
  options: QueryRunOptions
): Promise<unknown> => {
  // A running request is shared. A cancelled one is never handed to a new
  // reader: it will only reject, so a fresh run replaces it below.
  if (record.promise !== null && record.controller?.signal.aborted !== true) {
    return record.promise;
  }

  record.options = options;

  const controller = new AbortController();
  record.controller = controller;
  patchState(record, { fetchStatus: "fetching" });

  const attempt = async (failureCount: number): Promise<unknown> => {
    try {
      return await options.fn({ key: record.key, signal: controller.signal });
    } catch (error) {
      if (controller.signal.aborted || !shouldRetry(failureCount, error)) {
        throw error;
      }

      await wait(
        Math.min(800 * 2 ** failureCount, MAX_RETRY_DELAY),
        controller.signal
      );

      return await attempt(failureCount + 1);
    }
  };

  const promise = attempt(0)
    .then(
      (data) => {
        if (record.controller !== controller) {
          // A replaced run must not overwrite the run that replaced it.
          return data;
        }

        record.updatedAt = performance.now();

        patchState(record, {
          data,
          dataUpdateCount: record.state.dataUpdateCount + 1,
          error: null,
          fetchStatus: "idle",
          invalidated: false,
          status: "success",
        });

        return data;
      },
      (error: unknown) => {
        if (record.controller !== controller) {
          // A replaced run must not overwrite the run that replaced it.
          throw error;
        }

        if (controller.signal.aborted) {
          // A cancelled request leaves the record as it was.
          patchState(record, { fetchStatus: "idle" });
        } else {
          patchState(record, {
            error,
            errorUpdatedAt: Date.now(),
            fetchStatus: "idle",
            status: "error",
          });
        }

        throw error;
      }
    )
    .finally(() => {
      if (record.controller === controller) {
        record.controller = null;
        record.promise = null;
        scheduleGc(record, options.gcTime);
      }
    });

  record.promise = promise;

  return promise;
};

/** FetchQuery: fresh data is returned; otherwise the request runs once. */
const fetchQuery = async (
  key: readonly unknown[],
  options: QueryRunOptions
): Promise<unknown> => {
  const record = recordFor(key);

  if (isFresh(record, options.staleTime)) {
    scheduleGc(record, options.gcTime);

    return record.state.data;
  }

  return await runQuery(record, options);
};

const setQueryData = (
  key: readonly unknown[],
  data: unknown,
  gcTime = IMAGE_CACHE_TTL_MS
) => {
  const record = recordFor(key);
  record.updatedAt = performance.now();

  patchState(record, {
    data,
    dataUpdateCount: record.state.dataUpdateCount + 1,
    error: null,
    invalidated: false,
    status: "success",
  });

  scheduleGc(record, gcTime);
};

const observe = (record: QueryRecord, gcTime: number, listener: () => void) => {
  clearTimeout(record.gcTimer);

  if (record.observers === 0) {
    record.mountedAt = record.state.dataUpdateCount;
  }

  record.observers += 1;
  record.listeners.add(listener);

  return () => {
    record.listeners.delete(listener);
    record.observers -= 1;

    if (record.observers === 0) {
      // The last observer left: stop the request, as the query client does.
      record.controller?.abort();
      scheduleGc(record, gcTime);
    }
  };
};

interface UseQueryOptions {
  enabled: boolean;
  fn?: QueryRunOptions["fn"];
  gcTime?: number;
  key: readonly unknown[];
  staleTime?: number;
}

interface QueryResult {
  data: unknown;
  fetchStatus: "fetching" | "idle";
  isError: boolean;
  isFetchedAfterMount: boolean;
  isLoading: boolean;
  isSuccess: boolean;
  refetch: () => void;
  status: QueryStatus;
}

const noop = () => {
  // Nothing to observe or undo.
};

/** UseQuery over the store above. */
const useQuery = ({
  enabled,
  fn,
  gcTime = IMAGE_CACHE_TTL_MS,
  key,
  staleTime = IMAGE_CACHE_TTL_MS,
}: UseQueryOptions): QueryResult => {
  const hash = hashKey(key);
  const keyRef = useRef(key);

  useInsertionEffect(() => {
    keyRef.current = key;
  });

  // The subscription follows the key: a new hash is a new record to observe.
  const subscribe = useCallback(
    (listener: () => void) =>
      observe(records.get(hash) ?? recordFor(keyRef.current), gcTime, listener),
    [gcTime, hash]
  );

  const state = useSyncExternalStore(
    subscribe,
    () => records.get(hash)?.state ?? INITIAL_STATE,
    () => INITIAL_STATE
  );

  const run = useCallback(
    (force: boolean) => {
      if (fn === undefined) {
        return;
      }

      const options = { fn, gcTime, staleTime };
      const record = recordFor(keyRef.current);

      if (force) {
        patchState(record, { invalidated: true });
      }

      if (!isFresh(record, staleTime)) {
        runQuery(record, options).catch(noop);
      }
    },
    [fn, gcTime, staleTime]
  );

  useEffect(() => {
    if (enabled) {
      run(false);
    }
    // The request starts again when the key (its hash) changes.
    // oxlint-disable-next-line react/exhaustive-effect-dependencies
  }, [enabled, hash, run]);

  const mounted = records.get(hash)?.mountedAt;

  return {
    data: state.data,
    fetchStatus: state.fetchStatus,
    isError: state.status === "error",
    isFetchedAfterMount:
      mounted !== undefined && state.dataUpdateCount > mounted,
    isLoading: state.fetchStatus === "fetching" && state.status === "pending",
    isSuccess: state.status === "success",
    refetch: () => {
      run(true);
    },
    status: state.status,
  };
};

/* ------------------------------------------------------ asset query --- */

/** The cache identity of an asset. */
export const imageAssetQueryKey = (
  pointer: string,
  resolver: ImageAssetResolver | null | undefined
): readonly unknown[] => [
  "file",
  "image-src",
  pointer,
  ...(resolver?.cacheKey ?? ["images"]),
  ...(resolver?.validationSessionId === undefined
    ? []
    : [resolver.validationSessionId]),
];

const imageCheckKey = (key: readonly unknown[]) => [
  "file",
  "image-check",
  ...key.slice(2),
];

/** A blob as a data URL. */
const blobToDataUrl = (blob: Blob) =>
  new Promise<string>((resolve, reject) => {
    const reader = new FileReader();

    reader.addEventListener("load", () => {
      resolve(typeof reader.result === "string" ? reader.result : "");
    });

    reader.addEventListener("error", () => {
      reject(reader.error ?? new Error("Could not read the image"));
    });

    reader.readAsDataURL(blob);
  });

const resourceTimingOf = (url: string): ImageLoadTiming["resourceTiming"] => {
  const entry = performance
    .getEntriesByName(url, "resource")
    .findLast((candidate) => candidate.entryType === "resource");

  if (entry === undefined || !(entry instanceof PerformanceResourceTiming)) {
    return undefined;
  }

  return {
    decoded_body_size: entry.decodedBodySize,
    encoded_body_size: entry.encodedBodySize,
    initiator_type: entry.initiatorType,
    resource_duration_ms: entry.duration,
    transfer_size: entry.transferSize,
  };
};

/**
 * An object URL for a downloaded blob, released once its record is
 * removed or replaced, or the request is cancelled.
 */
const retainObjectUrl = (
  key: readonly unknown[],
  blob: Blob,
  signal: AbortSignal
): string => {
  const url = URL.createObjectURL(blob);
  objectUrlBlobs.set(url, blob);

  const hash = hashKey(key);

  const stops: (() => void)[] = [];

  const release = () => {
    for (const stop of stops) {
      stop();
    }

    setTimeout(() => {
      objectUrlBlobs.delete(url);
      URL.revokeObjectURL(url);
    }, 0);
  };

  const onRemoved = (record: QueryRecord) => {
    if (record.hash === hash) {
      release();
    }
  };

  const onUpdated = (record: QueryRecord) => {
    if (record.hash !== hash) {
      return;
    }

    const data = dataOf<AssetQueryData>(record.state.data);

    if (
      record.state.fetchStatus === "idle" &&
      (data?.kind !== "download" || data.objectUrl !== url)
    ) {
      release();
    }
  };

  removalListeners.add(onRemoved);
  updateListeners.add(onUpdated);
  signal.addEventListener("abort", release, { once: true });

  stops.push(
    () => {
      removalListeners.delete(onRemoved);
    },
    () => {
      updateListeners.delete(onUpdated);
    },
    () => {
      signal.removeEventListener("abort", release);
    }
  );

  return url;
};

/** The download URL of the default `/files/download/{id}` reply. */
const downloadUrlOfReply = (reply: unknown): string => {
  const fields =
    typeof reply === "object" && reply !== null
      ? Object.fromEntries(Object.entries(reply))
      : null;

  const status = typeof fields?.status === "string" ? fields.status : undefined;

  const url =
    typeof fields?.download_url === "string" ? fields.download_url : "";

  if (
    fields === null ||
    (status !== undefined && status !== "success") ||
    url.length === 0
  ) {
    throw new Error("No download address could be obtained");
  }

  return url;
};

/**
 * With no resolver the file id is looked up on the app's own
 * download endpoint.
 */
const defaultResolveAsset = async (
  fileId: string,
  signal: AbortSignal
): Promise<ImageAssetResolution> => {
  const response = await fetch(
    `/files/download/${encodeURIComponent(fileId)}`,
    { signal }
  );

  if (!response.ok) {
    throw Object.assign(new Error("No download address could be obtained"), {
      status: response.status,
    });
  }

  return {
    downloadUrl: downloadUrlOfReply(await response.json()),
    kind: "available",
  };
};

const resolveAsset = async (
  pointer: string,
  resolver: ImageAssetResolver | null | undefined,
  signal: AbortSignal
): Promise<ImageAssetResolution> => {
  const fileId = assetPointerFileId(pointer);

  if (resolver === null || resolver === undefined) {
    return await defaultResolveAsset(fileId, signal);
  }

  return await resolver.resolveAsset(fileId);
};

/** The query that resolves one asset pointer. */
const assetQueryFn =
  (
    pointer: string,
    resolver: ImageAssetResolver | null | undefined
  ): QueryRunOptions["fn"] =>
  async ({ key, signal }): Promise<AssetQueryData> => {
    const recordsChecks =
      resolver?.validationSessionId !== undefined &&
      resolver.imageLoading !== undefined;

    const recordCheck = (result: ImageCheckResult | null) => {
      if (recordsChecks) {
        setQueryData(
          imageCheckKey(key),
          result === null ? null : { completedAt: performance.now(), result }
        );
      }
    };

    recordCheck(null);

    let resolved: ImageAssetResolution;

    try {
      resolved = await resolveAsset(pointer, resolver, signal);
    } catch (error) {
      signal.throwIfAborted();

      if (!(error instanceof CancelledError)) {
        recordCheck("error");
      }

      throw error;
    }

    signal.throwIfAborted();
    recordCheck(resolved.kind === "available" ? "available" : "deleted");

    if (resolved.kind === "trashed") {
      return {
        kind: "deleted",
        state: { libraryFileId: resolved.libraryFileId, status: "trashed" },
      };
    }

    if (resolved.kind === "permanently-deleted") {
      return { kind: "deleted", state: { status: "permanently-deleted" } };
    }

    if (
      resolver?.useDownloadUrlAsImageSrc === true &&
      resolved.requestHeaders === undefined
    ) {
      return { kind: "url", url: resolved.downloadUrl };
    }

    const startedAt = performance.now();

    const response = await fetch(resolved.downloadUrl, {
      headers: resolved.requestHeaders,
      signal,
    });

    if (!response.ok) {
      throw Object.assign(new Error("Failed to download the image"), {
        status: response.status,
      });
    }

    const blob = await response.blob();
    signal.throwIfAborted();

    const dataUrl = await blobToDataUrl(blob);
    signal.throwIfAborted();

    return {
      blob,
      dataUrl,
      downloadUrl: resolved.downloadUrl,
      kind: "download",
      loadTiming: {
        resourceTiming: resourceTimingOf(resolved.downloadUrl),
        startedAt,
      },
      objectUrl: OBJECT_URL_TYPES.has(blob.type)
        ? retainObjectUrl(key, blob, signal)
        : null,
    };
  };

interface ImageCheck {
  completedAt: number;
  result: ImageCheckResult;
}

export interface AssetImage {
  dataUrl: string | null;
  deleted: DeletedImageState | undefined;
  imageCacheHit: boolean;
  imageCheck: ImageCheck | undefined;
  isError: boolean;
  isLoading: boolean;
  isShowingCachedImage: boolean;
  loadSource: string | undefined;
  loadTiming: ImageLoadTiming | undefined;
  refetch: () => void;
  src: string | null;
}

/** The successful request that came just before this one in the same scope. */
const previousSuccessfulKey = (
  key: readonly unknown[]
): readonly unknown[] | undefined => {
  const scope = key.slice(0, -1);
  const scopeHash = hashKey(scope);
  const hash = hashKey(key);

  const siblings = [...records.values()].filter(
    (record) =>
      record.key.length === key.length &&
      hashKey(record.key.slice(0, -1)) === scopeHash
  );

  const index = siblings.findIndex((record) => record.hash === hash);
  const previous = siblings[index - 1];

  const data = dataOf<AssetQueryData>(previous?.state.data);

  return previous !== undefined &&
    previous.state.status === "success" &&
    previous.state.fetchStatus === "idle" &&
    !previous.state.invalidated &&
    data?.kind !== "deleted"
    ? previous.key
    : undefined;
};

/** Resolves an asset pointer through the resolver. */
export const useAssetImage = (
  pointer: string,
  resolver: ImageAssetResolver | null | undefined,
  { enabled = true }: { enabled?: boolean } = {}
): AssetImage => {
  const key = imageAssetQueryKey(pointer, resolver);
  const active = enabled && pointer.length > 0;

  const resolverRef = useRef(resolver);

  useInsertionEffect(() => {
    resolverRef.current = resolver;
  });

  const fn = useCallback<QueryRunOptions["fn"]>(
    (context) => assetQueryFn(pointer, resolverRef.current)(context),
    [pointer]
  );

  const main = useQuery({ enabled: active, fn, key });
  const check = useQuery({ enabled: false, key: imageCheckKey(key) });
  const record = records.get(hashKey(key));
  const validating = resolver?.validationSessionId !== undefined;

  const previousKey =
    validating &&
    active &&
    record !== undefined &&
    record.state.errorUpdatedAt === 0 &&
    !record.state.invalidated
      ? previousSuccessfulKey(key)
      : undefined;

  const showingCached =
    resolver?.showCachedImageDuringValidation === true && main.isLoading
      ? previousKey
      : undefined;

  const cached = useQuery({
    enabled: false,
    key: showingCached ?? key,
  });

  let current = dataOf<AssetQueryData>(main.data);

  if (validating && !main.isSuccess) {
    current =
      showingCached === undefined
        ? undefined
        : dataOf<AssetQueryData>(cached.data);
  }

  const download = current?.kind === "download" ? current : null;
  const checkData = dataOf<ImageCheck | null>(check.data);

  const imageCheck =
    (record?.state.status === "pending" &&
      record.state.fetchStatus === "idle") ||
    (checkData?.result === "error" &&
      (!main.isError || record?.state.fetchStatus !== "idle"))
      ? undefined
      : (checkData ?? undefined);

  let src: string | null = null;

  if (current?.kind === "url") {
    src = current.url;
  } else if (download !== null) {
    src = download.objectUrl ?? download.dataUrl;
  }

  return {
    dataUrl: download?.dataUrl ?? null,
    deleted: current?.kind === "deleted" ? current.state : undefined,
    imageCacheHit: previousKey !== undefined,
    imageCheck,
    isError: main.isError,
    isLoading: main.isLoading && current === undefined,
    isShowingCachedImage: showingCached !== undefined && current !== undefined,
    loadSource: download?.downloadUrl,
    loadTiming:
      main.isSuccess && main.isFetchedAfterMount
        ? download?.loadTiming
        : undefined,
    refetch: main.refetch,
    src,
  };
};

/* ------------------------------------------------------- local files --- */

interface LocalImage {
  base64: string;
  mimeType: string;
}

/** The data of a local file read through the host, or null. */
const readLocalImage = async (
  path: string,
  host: ImageSourceHost,
  hostId: string,
  conversationId: string | null | undefined,
  environmentId: string | undefined,
  signal?: AbortSignal
): Promise<LocalImage | null> => {
  const request: LocalFileRequest = {
    conversationId,
    environmentId,
    hostId,
    path,
  };

  try {
    const reply = await fetchQuery(["workspace-file-binary", request], {
      fn: async ({ signal: querySignal }) => {
        if (host.readBinary === null) {
          throw new Error("This host cannot read files as bytes");
        }

        return await host.readBinary(
          request,
          signal === undefined
            ? querySignal
            : AbortSignal.any([querySignal, signal])
        );
      },
      gcTime: IMAGE_CACHE_TTL_MS,
      staleTime:
        hostId === DURABLE_HOST_ID &&
        conversationId !== null &&
        conversationId !== undefined &&
        environmentId === undefined
          ? 0
          : Number.POSITIVE_INFINITY,
    });

    const contents = dataOf<{ contentsBase64?: string }>(reply);
    const base64 = contents?.contentsBase64;

    return base64 === undefined || base64 === ""
      ? null
      : { base64, mimeType: mimeTypeOf(path) };
  } catch {
    // The component logs a warning and shows nothing for a file it cannot read.
    return null;
  }
};

/** A local file as a data URL, or null. */
export const readLocalFileDataUrl = async (
  src: string,
  host: ImageSourceHost,
  hostId: string,
  conversationId?: string | null,
  environmentId?: string,
  signal?: AbortSignal
): Promise<string | null> => {
  const path = localFilePath(src);

  if (path === null) {
    return null;
  }

  const image = await readLocalImage(
    path,
    host,
    hostId,
    conversationId,
    environmentId,
    signal
  );

  return image === null
    ? null
    : `data:${image.mimeType};base64,${image.base64}`;
};

/* ------------------------------------------------------------- hook --- */

export interface GeneratedImageSourceOptions {
  conversationId?: string | null;
  hostId?: string | null;
  imageAssetResolver?: ImageAssetResolver | null;
  shouldLoadFileDataUrl?: boolean;
  src: string;
}

export interface GeneratedImageSource extends Omit<
  AssetImage,
  "isLoading" | "src"
> {
  downloadSrc: string | null;
  previewSrc: string | null;
}

interface LocalFileState {
  dataUrl: string | null;
  environmentId: string | undefined;
  src: string;
}

/** Chooses the resolved asset, host file URL, plain URL or host data URL. */
export const useGeneratedImageSource = ({
  conversationId,
  hostId,
  imageAssetResolver,
  shouldLoadFileDataUrl,
  src,
}: GeneratedImageSourceOptions): GeneratedImageSource & {
  dataUrl: string | null;
} => {
  const host = useContext(ImageSourceHostContext);

  const conversationHostId =
    conversationId === null || conversationId === undefined
      ? null
      : host.conversationHostId(conversationId);

  const resolvedHostId = hostId ?? conversationHostId ?? LOCAL_HOST_ID;
  const hostKind = host.hostKind(resolvedHostId);

  const environment =
    conversationId === null || conversationId === undefined
      ? null
      : host.conversationEnvironment(conversationId);

  const environmentId =
    environment?.hostId === resolvedHostId
      ? environment.environmentId
      : undefined;

  const [localFile, setLocalFile] = useState<LocalFileState | null>(null);

  const hasSource = src.trim().length > 0;
  const assetSrc = hasSource && isAssetUrl(src) ? src : "";
  const asset = useAssetImage(assetSrc, imageAssetResolver);
  const localPath = hasSource ? localFilePath(src) : null;

  const localUrl =
    hostKind.kind === "local" &&
    hostKind.id === resolvedHostId &&
    localPath !== null
      ? localFileUrl(localPath)
      : null;

  const readDataUrl =
    localFile?.src === src && localFile.environmentId === environmentId
      ? localFile.dataUrl
      : null;

  let previewSrc: string | null = null;

  if (hasSource) {
    previewSrc =
      asset.src ??
      localUrl ??
      (localPath === null && assetSrc === "" ? src : readDataUrl);
  }

  useEffect(() => {
    if (
      localPath === null ||
      (localUrl !== null && shouldLoadFileDataUrl !== true)
    ) {
      return noop;
    }

    let cancelled = false;
    // The state is set here, then again once the file has been read.
    // oxlint-disable-next-line react/set-state-in-effect
    setLocalFile({ dataUrl: null, environmentId, src });

    const load = async () => {
      const dataUrl = await readLocalFileDataUrl(
        src,
        host,
        resolvedHostId,
        conversationId,
        environmentId
      );

      if (!cancelled) {
        setLocalFile({ dataUrl, environmentId, src });
      }
    };

    load().catch(noop);

    return () => {
      // oxlint-disable-next-line react/immutability -- local to this effect or callback, not render state; oxlint 1.91 misreports it
      cancelled = true;
    };
  }, [
    conversationId,
    environmentId,
    host,
    localPath,
    localUrl,
    resolvedHostId,
    shouldLoadFileDataUrl,
    src,
  ]);

  const dataUrl =
    asset.dataUrl ??
    readDataUrl ??
    (src.startsWith("data:image/") ? src : null);

  return {
    dataUrl,
    deleted: asset.deleted,
    downloadSrc: asset.dataUrl ?? readDataUrl ?? previewSrc,
    imageCacheHit: asset.imageCacheHit,
    imageCheck: asset.imageCheck,
    isError: assetSrc !== "" && asset.isError,
    isShowingCachedImage: asset.isShowingCachedImage,
    loadSource: asset.loadSource,
    loadTiming: asset.loadTiming,
    previewSrc,
    refetch: asset.refetch,
  };
};

"use client";

/* oxlint-disable eslint/complexity, react/refs, shadcn/no-restyle, shadcn/no-arbitrary-values, anti-slop/no-runtime-typeof -- The viewer restyles one frame and its own round controls with measured values that have no theme token, and probes pointer-capture methods the way the component does. */

import {
  ViewerArrowLeftIcon,
  ViewerCloseIcon,
  ViewerDownloadIcon,
  ViewerMinusIcon,
  ViewerPlusIcon,
} from "@/components/carousel/icons";
import { blobForObjectUrl } from "@/components/carousel/image-source";
import {
  registerImageViewerZoomHandler,
  registerOpenImageViewer,
} from "@/components/carousel/zoom-bridge";
import type { ImageViewerZoomCommand } from "@/components/carousel/zoom-bridge";
import { Button } from "@/components/ui/button";
import { Dialog, DialogTitle } from "@/components/ui/dialog";
import type { LayerEvent } from "@/lib/dismissable-layer";
import { cn } from "@/lib/utils";
import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useInsertionEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import type {
  CSSProperties,
  PointerEvent as ReactPointerEvent,
  ReactEventHandler,
  ReactNode,
  RefObject,
} from "react";
import { flushSync } from "react-dom";

import styles from "../ui/carousel.module.css";

/*
 * The full-size image viewer: the dialog shell, close,
 * previous and next buttons, ArrowLeft and ArrowRight, the zoom ramp and zoom
 * controls, ctrl+wheel zoom, touch pan and pinch, the host zoom bridge,
 * download, toolbar, edit and content slots, inline rendering, portal
 * containment and the overlay presentation.
 */

/** The zoom ramp in percent. */
const ZOOM_RAMP = [
  25, 33, 50, 67, 75, 80, 90, 100, 110, 125, 150, 175, 200, 250, 300, 400, 500,
] as const;

/** The ctrl+wheel divisor. */
const WHEEL_ZOOM_DIVISOR = 220;

const LINE_HEIGHT_PX = 16;
const PAGE_HEIGHT_PX = 768;

interface Size {
  height: number;
  width: number;
}

interface Point {
  clientX: number;
  clientY: number;
}

interface ZoomState {
  src: string;
  zoomPercent: number;
}

interface NaturalSize extends Size {
  src: string;
}

interface PanState extends Point {
  pointerId: number;
  scrollLeft: number;
  scrollTop: number;
}

interface PinchState {
  distance: number;
  zoomPercent: number;
}

/** The percent at which the whole image fits (never above 100). */
const fitPercent = (
  naturalSize: Size | null,
  viewportSize: Size | null
): number | null => {
  if (viewportSize === null || naturalSize === null) {
    return null;
  }

  const width = viewportSize.width / naturalSize.width;
  const height = viewportSize.height / naturalSize.height;
  const fit = Math.min(1, width, height);

  return !Number.isFinite(fit) || fit <= 0 ? null : fit * 100;
};

/** The ramp with the fit percent inserted in order. */
const zoomRampFor = (fit: number | null): number[] => {
  const ramp: number[] = [...ZOOM_RAMP];

  if (fit !== null && !ramp.includes(fit)) {
    ramp.push(fit);
    ramp.sort((a, b) => a - b);
  }

  return ramp;
};

/** The next ramp step above or below the current percent. */
const stepZoom = (
  current: number,
  direction: "in" | "out",
  ramp: number[]
): number => {
  if (direction === "in") {
    return ramp.find((step) => step > current) ?? ramp.at(-1) ?? current;
  }

  return ramp.findLast((step) => step < current) ?? ramp[0] ?? current;
};

const clampZoom = (
  maximum: number | null,
  minimum: number | null,
  zoomPercent: number
): number | null =>
  minimum === null || maximum === null || !Number.isFinite(zoomPercent)
    ? null
    : Math.min(maximum, Math.max(minimum, zoomPercent));

/** Wheel delta in pixels. */
const wheelDeltaPixels = (event: WheelEvent): number => {
  if (event.deltaMode === 1) {
    return event.deltaY * LINE_HEIGHT_PX;
  }

  return event.deltaMode === 2 ? event.deltaY * PAGE_HEIGHT_PX : event.deltaY;
};

const insideRect = (point: Point, rect: DOMRect) =>
  point.clientX >= rect.left &&
  point.clientX <= rect.right &&
  point.clientY >= rect.top &&
  point.clientY <= rect.bottom;

/** The zoom anchor for a wheel event. */
const wheelAnchor = (
  event: WheelEvent,
  fallbackPoint: Point | null,
  viewport: HTMLElement | null
): Point => {
  const point = { clientX: event.clientX, clientY: event.clientY };

  if (viewport === null) {
    return point;
  }

  const rect = viewport.getBoundingClientRect();

  if ((point.clientX !== 0 || point.clientY !== 0) && insideRect(point, rect)) {
    return point;
  }

  if (fallbackPoint !== null && insideRect(fallbackPoint, rect)) {
    return fallbackPoint;
  }

  return {
    clientX: rect.left + rect.width / 2,
    clientY: rect.top + rect.height / 2,
  };
};

/** The midpoint and distance of the first two touches. */
const pinchOf = (pointers: Map<number, Point>) => {
  const [first, second] = [...pointers.values()];

  if (first === undefined || second === undefined) {
    return null;
  }

  const distance = Math.hypot(
    first.clientX - second.clientX,
    first.clientY - second.clientY
  );

  return distance <= 0
    ? null
    : {
        clientX: (first.clientX + second.clientX) / 2,
        clientY: (first.clientY + second.clientY) / 2,
        distance,
      };
};

/** A ratio clamped to 0..1, 0.5 when not finite. */
const unitRatio = (value: number) =>
  Number.isFinite(value) ? Math.min(1, Math.max(0, value)) : 0.5;

/** Arrow keys do not navigate from editable or widget elements. */
const NAVIGATION_BLOCKERS =
  'input, textarea, select, [role="slider"], [role="spinbutton"], [role="combobox"], [role="listbox"], [role="grid"], [role="tree"], [role="tablist"], [role="menu"]';

const allowsArrowNavigation = (target: EventTarget): boolean => {
  if (!(target instanceof HTMLElement)) {
    return true;
  }

  const editable = target.closest("[contenteditable]");

  return (
    !target.isContentEditable &&
    (editable === null ||
      editable.getAttribute("contenteditable") === "false") &&
    target.closest(NAVIGATION_BLOCKERS) === null
  );
};

/** An effect cleanup for the paths that set nothing up. */
const noCleanup = () => {
  // Nothing was set up, so there is nothing to undo.
};

const pointOf = (event: ReactPointerEvent): Point => ({
  clientX: event.clientX,
  clientY: event.clientY,
});

/* ------------------------------------------------------------------ zoom --- */

/**
 * The zoom state of the viewer: the viewport node and size, the
 * image's natural size, the zoom percent and every way to change it.
 */
const useImageZoom = (
  src: string,
  viewportRef: RefObject<HTMLDivElement | null>,
  lastPointerRef: RefObject<Point | null>,
  givenSize: Size | null
) => {
  const [viewport, setViewport] = useState<HTMLDivElement | null>(null);
  const [viewportSize, setViewportSize] = useState<Size | null>(null);
  const [zoomState, setZoomState] = useState<ZoomState | null>(null);
  const [naturalState, setNaturalState] = useState<NaturalSize | null>(null);
  const imageRef = useRef<HTMLElement | null>(null);

  const onWheelRef = useRef<(event: WheelEvent) => void>(() => {
    // Replaced on every render below.
  });

  // The size the caller gives, else the size the image reported.
  const naturalSize =
    givenSize ?? (naturalState?.src === src ? naturalState : null);

  const fit = fitPercent(naturalSize, viewportSize);
  const explicitZoom = zoomState?.src === src ? zoomState.zoomPercent : null;
  const zoomPercent = explicitZoom ?? fit;
  const ramp = zoomRampFor(fit);
  const minimumZoom = ramp[0] ?? zoomPercent;
  const maximumZoom = ramp.at(-1) ?? zoomPercent;

  const canZoomOut =
    zoomPercent !== null && minimumZoom !== null && zoomPercent > minimumZoom;

  const canZoomIn =
    zoomPercent !== null && maximumZoom !== null && zoomPercent < maximumZoom;

  const measureViewport = useCallback((node: HTMLElement) => {
    const rect = node.getBoundingClientRect();
    const zoom = node.currentCSSZoom || 1;
    const width = rect.width / zoom;
    const height = rect.height / zoom;

    setViewportSize((previous) =>
      previous?.width === width && previous.height === height
        ? previous
        : { height, width }
    );
  }, []);

  const readNaturalSize = useCallback(
    (image: HTMLImageElement) => {
      const { naturalHeight, naturalWidth } = image;

      if (naturalWidth === 0 || naturalHeight === 0) {
        return;
      }

      if (viewportRef.current !== null) {
        measureViewport(viewportRef.current);
      }

      setNaturalState({ height: naturalHeight, src, width: naturalWidth });
    },
    [measureViewport, src, viewportRef]
  );

  const decodeThenRead = useCallback(
    async (image: HTMLImageElement) => {
      try {
        await image.decode();
      } catch {
        return;
      }

      if (image.isConnected && image.getAttribute("src") === src) {
        readNaturalSize(image);
      }
    },
    [readNaturalSize, src]
  );

  const attachImage = useCallback(
    (image: HTMLImageElement | null) => {
      imageRef.current = image;

      if (image?.decode !== undefined) {
        void decodeThenRead(image);
      }
    },
    [decodeThenRead]
  );

  const attachContent = useCallback((node: HTMLDivElement | null) => {
    imageRef.current = node;
  }, []);

  const attachViewport = useCallback(
    (node: HTMLDivElement | null) => {
      viewportRef.current = node;
      setViewport(node);
    },
    [viewportRef]
  );

  const zoomAround = ({
    clientX,
    clientY,
    zoomPercent: nextPercent,
  }: Point & { zoomPercent: number }) => {
    const node = viewportRef.current;
    const image = imageRef.current;

    if (node === null || image === null) {
      setZoomState({ src, zoomPercent: nextPercent });

      return;
    }

    const before = image.getBoundingClientRect();

    const ratioX =
      before.width > 0
        ? unitRatio((clientX - before.left) / before.width)
        : 0.5;

    const ratioY =
      before.height > 0
        ? unitRatio((clientY - before.top) / before.height)
        : 0.5;

    flushSync(() => {
      setZoomState({ src, zoomPercent: nextPercent });
    });

    if (!node.isConnected || !image.isConnected) {
      return;
    }

    const after = image.getBoundingClientRect();
    node.scrollLeft += after.left + after.width * ratioX - clientX;
    node.scrollTop += after.top + after.height * ratioY - clientY;
  };

  const step = (direction: "in" | "out") => {
    const node = viewportRef.current;

    if (zoomPercent === null) {
      return;
    }

    const next = stepZoom(zoomPercent, direction, ramp);

    if (node === null) {
      setZoomState({ src, zoomPercent: next });

      return;
    }

    const rect = node.getBoundingClientRect();

    zoomAround({
      clientX: rect.left + rect.width / 2,
      clientY: rect.top + rect.height / 2,
      zoomPercent: next,
    });
  };

  // The wheel listener is native and non-passive so ctrl+wheel can cancel the
  // browser page zoom; it reads the latest state through this ref.
  useEffect(() => {
    onWheelRef.current = (event) => {
      if (!event.ctrlKey || zoomPercent === null) {
        return;
      }

      event.preventDefault();
      event.stopPropagation();

      const next = clampZoom(
        maximumZoom,
        minimumZoom,
        zoomPercent * Math.exp(-wheelDeltaPixels(event) / WHEEL_ZOOM_DIVISOR)
      );

      if (next === null || next === zoomPercent) {
        return;
      }

      const anchor = wheelAnchor(
        event,
        lastPointerRef.current,
        viewportRef.current
      );

      zoomAround({ ...anchor, zoomPercent: next });
    };
  });

  useEffect(() => {
    if (viewport === null) {
      return noCleanup;
    }

    const handler = (event: WheelEvent) => {
      onWheelRef.current(event);
    };

    viewport.addEventListener("wheel", handler, { passive: false });

    return () => {
      viewport.removeEventListener("wheel", handler);
    };
  }, [viewport]);

  // ResizeObserver reports the size once on observe, which sets the first size.
  useEffect(() => {
    if (viewport === null || typeof ResizeObserver === "undefined") {
      return noCleanup;
    }

    const observer = new ResizeObserver(() => {
      measureViewport(viewport);
    });

    observer.observe(viewport);

    return () => {
      observer.disconnect();
    };
  }, [measureViewport, viewport]);

  return [
    {
      canZoomIn,
      canZoomOut,
      maximumZoom,
      minimumZoom,
      naturalSize,
      zoomPercent,
    },
    {
      attachContent,
      attachImage,
      attachViewport,
      clearZoom: () => {
        setZoomState(null);
      },
      readNaturalSize,
      // Back to fit, and both scroll offsets to zero.
      resetZoom: () => {
        setZoomState(null);

        const node = viewportRef.current;

        if (node !== null) {
          node.scrollLeft = 0;
          node.scrollTop = 0;
        }
      },
      step,
      zoomAround,
    },
  ] as const;
};

/* -------------------------------------------------------------- touch --- */

type ZoomView = ReturnType<typeof useImageZoom>[0];

type ZoomActions = ReturnType<typeof useImageZoom>[1];

/** Touch pan and pinch of the viewport. */
const useTouchGestures = (
  zoomView: ZoomView,
  zoomActions: ZoomActions,
  viewportRef: RefObject<HTMLDivElement | null>,
  lastPointerRef: RefObject<Point | null>
) => {
  const touchesRef = useRef(new Map<number, Point>());
  const panRef = useRef<PanState | null>(null);
  const pinchRef = useRef<PinchState | null>(null);

  const { maximumZoom, minimumZoom, zoomPercent } = zoomView;

  const panFrom = (pointerId: number, point: Point): PanState | null => {
    const node = viewportRef.current;

    return node === null
      ? null
      : {
          ...point,
          pointerId,
          scrollLeft: node.scrollLeft,
          scrollTop: node.scrollTop,
        };
  };

  const pinchFromTouches = (): PinchState | null => {
    const pinch = pinchOf(touchesRef.current);

    return pinch === null || zoomPercent === null
      ? null
      : { distance: pinch.distance, zoomPercent };
  };

  const reset = () => {
    touchesRef.current.clear();
    panRef.current = null;
    pinchRef.current = null;
  };

  const onPointerDown = (event: ReactPointerEvent<HTMLDivElement>) => {
    lastPointerRef.current = pointOf(event);

    if (event.pointerType !== "touch") {
      return;
    }

    if (typeof event.currentTarget.setPointerCapture === "function") {
      event.currentTarget.setPointerCapture(event.pointerId);
    }

    touchesRef.current.set(event.pointerId, pointOf(event));

    if (touchesRef.current.size === 1 && viewportRef.current !== null) {
      panRef.current = panFrom(event.pointerId, pointOf(event));

      return;
    }

    panRef.current = null;
    pinchRef.current = pinchFromTouches();
  };

  const onPinchMove = (event: ReactPointerEvent<HTMLDivElement>) => {
    event.preventDefault();
    event.stopPropagation();
    panRef.current = null;

    const start = pinchRef.current;
    const pinch = pinchOf(touchesRef.current);

    if (start === null || pinch === null) {
      return;
    }

    const next = clampZoom(
      maximumZoom,
      minimumZoom,
      start.zoomPercent * (pinch.distance / start.distance)
    );

    if (next !== null && next !== zoomPercent) {
      zoomActions.zoomAround({
        clientX: pinch.clientX,
        clientY: pinch.clientY,
        zoomPercent: next,
      });
    }
  };

  const onPointerMove = (event: ReactPointerEvent<HTMLDivElement>) => {
    lastPointerRef.current = pointOf(event);

    if (
      event.pointerType !== "touch" ||
      !touchesRef.current.has(event.pointerId)
    ) {
      return;
    }

    touchesRef.current.set(event.pointerId, pointOf(event));

    if (touchesRef.current.size > 1) {
      onPinchMove(event);

      return;
    }

    const node = viewportRef.current;
    const pan = panRef.current;

    if (node !== null && pan !== null && pan.pointerId === event.pointerId) {
      event.preventDefault();
      event.stopPropagation();
      node.scrollLeft = pan.scrollLeft - (event.clientX - pan.clientX);
      node.scrollTop = pan.scrollTop - (event.clientY - pan.clientY);
    }
  };

  const onPointerUp = (event: ReactPointerEvent<HTMLDivElement>) => {
    if (event.pointerType !== "touch") {
      return;
    }

    touchesRef.current.delete(event.pointerId);

    const target = event.currentTarget;

    if (
      typeof target.hasPointerCapture === "function" &&
      typeof target.releasePointerCapture === "function" &&
      target.hasPointerCapture(event.pointerId)
    ) {
      target.releasePointerCapture(event.pointerId);
    }

    if (touchesRef.current.size === 0) {
      panRef.current = null;
      pinchRef.current = null;

      return;
    }

    const remaining = touchesRef.current.entries().next().value;

    if (touchesRef.current.size === 1 && remaining !== undefined) {
      panRef.current = panFrom(remaining[0], remaining[1]);
      pinchRef.current = null;

      return;
    }

    panRef.current = null;
    pinchRef.current = pinchFromTouches();
  };

  return { onPointerDown, onPointerMove, onPointerUp, reset };
};

/* ------------------------------------------------------------ download --- */

/** A file name the host file system accepts, at most 254 bytes. */
const safeFileName = (name: string): string => {
  const cleaned = name
    .replaceAll(/[<>:"/\\|?*\p{Cc}]/gu, "_")
    .replaceAll(/[. ]+$/gu, "");

  const extension =
    /(?: \([\d.]{1,10}x\))?(?:-\d{1,10})?\.[a-z0-9]{1,10}$/iu.exec(
      cleaned
    )?.[0] ?? "";

  const base = cleaned.slice(0, cleaned.length - extension.length);
  const encoder = new TextEncoder();

  const { read } = encoder.encodeInto(
    base,
    new Uint8Array(254 - encoder.encode(extension).length)
  );

  const trimmed = base.slice(0, read).replaceAll(/[. ]+$/gu, "") || "_";

  const reserved =
    /^(?:con|prn|aux|nul|com[1-9¹²³]|lpt[1-9¹²³])(?:\.|$)/iu.test(trimmed);

  return `${reserved ? "_" : ""}${trimmed}${extension}`;
};

/** The file extension a source names. */
const extensionOf = (src: string): string | null => {
  const dataType = /^data:image\/[a-z0-9.+-]+(?=[;,])/iu
    .exec(src)?.[0]
    ?.slice("data:image/".length);

  const path = src.split(/[?#]/u, 1)[0] ?? "";
  const dot = path.lastIndexOf(".");
  const suffix = dot === -1 ? "" : path.slice(dot + 1);
  const found = dataType ?? (/^[a-z0-9]+$/iu.test(suffix) ? suffix : undefined);

  if (found === undefined) {
    return null;
  }

  const lower = found.toLowerCase();

  if (lower === "svg+xml") {
    return "svg";
  }

  return lower === "jpeg" ? "jpg" : lower;
};

/** "Image <date>.<extension>". */
const generatedFileName = (extension: string): string => {
  const date = new Intl.DateTimeFormat(undefined, {
    day: "numeric",
    hour: "2-digit",
    minute: "2-digit",
    month: "short",
    second: "2-digit",
    year: "numeric",
  }).format(new Date());

  return safeFileName(`Image ${date}.${extension}`);
};

/** The name a link download suggests. */
const linkFileName = (src: string, alt: string): string => {
  if (alt.trim().length > 0) {
    return alt.trim();
  }

  if (src.startsWith("data:")) {
    return "image";
  }

  const last = (src.split(/[?#]/u, 1)[0] ?? "").split(/[\\/]/u).at(-1);

  if (last === undefined || last.length === 0) {
    return "image";
  }

  try {
    return decodeURIComponent(last);
  } catch {
    return last;
  }
};

/** A data URL as a blob. */
const dataUrlToBlob = (dataUrl: string): Blob => {
  const comma = dataUrl.indexOf(",");
  const header = dataUrl.slice(5, comma);
  const body = dataUrl.slice(comma + 1);
  const type = /^[^;]+/u.exec(header)?.[0] ?? "application/octet-stream";

  if (/;base64/iu.test(header)) {
    return new Blob(
      [Uint8Array.from(atob(body), (c) => c.codePointAt(0) ?? 0)],
      {
        type,
      }
    );
  }

  return new Blob([decodeURIComponent(body)], { type });
};

/** Saves a blob through a temporary link. */
const saveBlobThroughLink = (blob: Blob, fileName: string) => {
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = fileName;
  link.style.display = "none";
  document.body.append(link);
  link.click();
  link.remove();

  setTimeout(() => {
    URL.revokeObjectURL(url);
  }, 0);
};

/** The bytes behind a download source. */
const imageBlobFor = async (
  src: string,
  image: HTMLImageElement | null
): Promise<Blob | null> => {
  if (/^https?:/iu.test(src)) {
    const response = await fetch(src);

    return await response.blob();
  }

  if (src.startsWith("data:")) {
    return dataUrlToBlob(src);
  }

  if (src.startsWith("blob:")) {
    const known = blobForObjectUrl(src);

    if (known !== undefined) {
      return known;
    }
  }

  try {
    const response = await fetch(src);

    if (response.ok) {
      return await response.blob();
    }
  } catch (error) {
    if (!src.startsWith("blob:") || image === null) {
      throw error;
    }
  }

  if (src.startsWith("blob:") && image !== null) {
    const canvas = document.createElement("canvas");
    canvas.width = image.naturalWidth;
    canvas.height = image.naturalHeight;
    const context = canvas.getContext("2d");

    if (context === null) {
      return null;
    }

    context.drawImage(image, 0, 0);

    return dataUrlToBlob(canvas.toDataURL("image/png"));
  }

  return null;
};

/** What the host provides for saving a file. */
export interface ImageViewerHost {
  saveFile:
    | ((request: {
        fileName: string;
        source: Blob;
      }) => Promise<{ path?: string | null } | null | undefined>)
    | null;
}

export const ImageViewerHostContext = createContext<ImageViewerHost>({
  saveFile: null,
});

/** Saves the image through the host; false when it could not. */
const downloadThroughHost = async ({
  downloadSrc,
  host,
  image,
  onDownloaded,
  suggestedFileName,
}: {
  downloadSrc: string;
  host: ImageViewerHost;
  image: HTMLImageElement | null;
  onDownloaded?: () => void;
  suggestedFileName: string;
}): Promise<boolean> => {
  try {
    const blob = await imageBlobFor(downloadSrc, image);

    if (blob === null) {
      return false;
    }

    const extension =
      extensionOf(downloadSrc) === null
        ? extensionOf(`data:${blob.type};base64,`)
        : null;

    const fileName = safeFileName(
      extension === null
        ? suggestedFileName
        : suggestedFileName.replace(/\.[a-z0-9]+$/iu, `.${extension}`)
    );

    if (host.saveFile === null) {
      return false;
    }

    const saved = await host.saveFile({ fileName, source: blob });

    if (saved?.path !== null && saved?.path !== undefined) {
      onDownloaded?.();
    }

    return true;
  } catch {
    return false;
  }
};

