  renderPreview?: (props: {
    imageRef: (element: HTMLElement | null) => void;
  }) => ReactNode;
  renderBottomAction?: (className: string) => ReactNode;
  showDownload?: boolean;
  showZoomControls?: boolean;
  src: string;
  toolbarActions?: readonly ImageViewerAction[];
  toolbarContent?: ReactNode;
