}

/** A press that moves further than this is not a click. */
const CLICK_SLOP_PX = 6;

/** The element the picture is drawn by (the first image or zoomable block). */
const imageNode = (
  viewportRef: RefObject<HTMLDivElement | null>
): HTMLElement | null =>
  viewportRef.current?.querySelector<HTMLElement>("img, [class~='m-auto']") ??
  null;

/** The classic frame leaves room for the window title bar. */
const FrameElement = ({
  children,
  className,
  onPointerDown,
  plain,
  windowControlsRight,
}: {
  children: ReactNode;
  className: string;
  onPointerDown: (event: ReactPointerEvent<HTMLDivElement>) => void;
  plain: boolean;
  windowControlsRight: number;
}) => (
  <div
    className={cn(
      !plain &&
        cn(
          styles.windowContent,
          "[--window-titlebar-height:env(titlebar-area-height,0px)]"
        ),
      className
    )}
    data-ck-right-window-controls={
      !plain && windowControlsRight > 0 ? true : undefined
    }
    onPointerDown={onPointerDown}
  >
    {children}
  </div>
);

/** The download control: a custom handler, the host save button or a link. */
const DownloadControl = ({
  alt,
  ariaLabel,
  className,
  downloadSrc,
  fileName,
  host,
  isLink,
  onDownload,
  onDownloadClick,
  onDownloaded,
  onDownloadFailure,
  previewImage,
  src,
  swallowPointer,
}: {
  alt: string;
  ariaLabel: string;
  className: string;
  downloadSrc: string;
  fileName?: string;
  host: ImageViewerHost;
  isLink: boolean;
  onDownload?: () => void;
  onDownloadClick?: () => void;
  onDownloaded?: () => void;
  onDownloadFailure?: () => void;
  previewImage: () => HTMLElement | null;
  src: string;
  swallowPointer: (event: ReactPointerEvent) => void;
}) => {
  const saveThroughHost = async () => {
    const image = previewImage();

    const saved = await downloadThroughHost({
      downloadSrc,
      host,
      image: image instanceof HTMLImageElement ? image : null,
      onDownloaded,
      suggestedFileName:
        fileName ?? generatedFileName(extensionOf(downloadSrc) ?? "png"),
    });

    if (!saved) {
      onDownloadFailure?.();
    }
  };

  if (onDownload !== undefined) {
    return (
      <Button
        aria-label={ariaLabel}
        className={className}
        disabledAppearance="none"
        focusRing="none"
        onClick={(event) => {
          event.stopPropagation();
          onDownloadClick?.();
          onDownload();
        }}
        onPointerDown={swallowPointer}
        unstyled
      >
        <ViewerDownloadIcon className="size-3.5" />
      </Button>
    );
  }

  if (isLink) {
    return (
      <a
        aria-label={ariaLabel}
        className={className}
        download={fileName ?? linkFileName(src, alt)}
        href={downloadSrc}
        onClick={(event) => {
          onDownloadClick?.();

          if (downloadSrc.startsWith("data:")) {
            event.preventDefault();

            saveBlobThroughLink(
              dataUrlToBlob(downloadSrc),
              fileName ?? linkFileName(src, alt)
            );
          }
        }}
        onPointerDown={(event) => {
          event.stopPropagation();
        }}
      >
        <ViewerDownloadIcon className="size-3.5" />
      </a>
    );
  }

  return (
    <Button
      aria-label={ariaLabel}
      className={className}
      disabledAppearance="none"
      focusRing="none"
      onClick={(event) => {
        event.stopPropagation();
        onDownloadClick?.();

        saveThroughHost().catch(() => {
          onDownloadFailure?.();
        });
      }}
      onPointerDown={swallowPointer}
      unstyled
    >
      <ViewerDownloadIcon className="size-3.5" />
    </Button>
  );
};

/** A callback with a stable identity that always runs the latest closure. */
const useStableCallback = <Args extends unknown[], Result>(
  handler: (...args: Args) => Result
) => {
  const latest = useRef(handler);

  useInsertionEffect(() => {
    latest.current = handler;
  });

  return useCallback((...args: Args) => latest.current(...args), []);
};

const swallowPointer = (event: ReactPointerEvent) => {
  event.preventDefault();
  event.stopPropagation();
};

const CLOSEST_INTERACTIVE =
  'button, a, input, textarea, select, [role="menu"], [role="menuitem"], [contenteditable="true"]';

/**
 * The photo viewer dialog. `presentation` is classic (a dimmed
 * full-screen dialog) or overlay (an image frame whose backdrop and chrome the
 * caller styles), `inline` renders the content without a dialog, and
 * `containedInPortal` renders it into the portal context's element.
 */
export const ImageViewerDialog = ({
  alt,
  bottomContent,
  caption,
  closeAriaLabel = "Close image preview",
  containedInPortal,
  containerResizeEdges,
  controlsSurface = "opaque",
  dialogAriaLabel = "Image preview",
  disableOpenAnimation = false,
  downloadAriaLabel = "Download image",
  downloadFileName,
  downloadSrc,
  editButton,
  headerContent,
  imageDecoding,
  imageDisplaySize,
  imageDraggable,
  imageFetchPriority,
  imageLoading,
  imageReferrerPolicy,
  imageSurface = "plain",
  inline = false,
  modal = true,
  nextAriaLabel = "Next image",
  nextDisabled = false,
  onCloseAutoFocus,
  onDownload,
  onDownloadClick,
  onDownloaded,
  onDownloadFailure,
  onImageError,
  onImageLoad,
  onNextImage,
  onOpenAutoFocus,
  onOpenChange,
  onPreviousImage,
  open,
  portalContainer,
  presentation = "classic",
  previewContent,
  previousAriaLabel = "Previous image",
  previousDisabled = false,
  renderBottomAction,
  renderPreview,
  showDownload = true,
  showZoomControls = true,
  src,
  toolbarActions,
  toolbarContent,
  toolbarLeadingAction,
  triggerContent,
  zoomableContent,
}: ImageViewerDialogProps) => {
  const viewportRef = useRef<HTMLDivElement | null>(null);
  const lastPointerRef = useRef<Point | null>(null);
  const previewNodeRef = useRef<HTMLElement | null>(null);
  const clickStartRef = useRef<Point | null>(null);
  const contextPortal = useContext(ImageViewerPortalContext);
  const host = useContext(ImageViewerHostContext);
  const windowControls = useContext(WindowControlsInsetContext);

  const overlay = presentation === "overlay";
  const container = portalContainer ?? contextPortal;
  const contained = containedInPortal ?? contextPortal !== null;
  const surface = downloadSrc ?? src;

  const [zoomView, zoomActions] = useImageZoom(
    src,
    viewportRef,
    lastPointerRef,
    zoomableContent ?? imageDisplaySize ?? null
  );

  const touch = useTouchGestures(
    zoomView,
    zoomActions,
    viewportRef,
    lastPointerRef
  );

  const { naturalSize, zoomPercent } = zoomView;

  const hasNavigation =
    onPreviousImage !== undefined || onNextImage !== undefined;

  const percentLabel = useMemo(
    () =>
      zoomPercent === null
        ? null
        : new Intl.NumberFormat(undefined, {
            maximumFractionDigits: 0,
            style: "percent",
          }).format(zoomPercent / 100),
    [zoomPercent]
  );

  // The zoomed size reaches the stylesheet through custom properties.
  const contentSize:
    | (CSSProperties & Record<`--${string}`, string>)
    | undefined =
    zoomPercent !== null && naturalSize !== null
      ? {
          "--ck-viewer-image-height": `${naturalSize.height * (zoomPercent / 100)}px`,
          "--ck-viewer-image-width": `${naturalSize.width * (zoomPercent / 100)}px`,
        }
      : undefined;

  // Leaving an image drops the touch state and the zoom.
  const resetGestures = () => {
    touch.reset();
    zoomActions.clearZoom();
  };

  const showPrevious = () => {
    if (onPreviousImage === undefined || previousDisabled) {
      return;
    }

    resetGestures();
    onPreviousImage();
  };

  const showNext = () => {
    if (onNextImage === undefined || nextDisabled) {
      return;
    }

    resetGestures();
    onNextImage();
  };

  const changeOpen = (nextOpen: boolean) => {
    if (!nextOpen) {
      resetGestures();
    }

    onOpenChange(nextOpen);
  };

  // The host's zoom menu commands.
  const onHostZoom = useStableCallback((command: ImageViewerZoomCommand) => {
    if (command.type === "step-zoom") {
      zoomActions.step(command.delta > 0 ? "in" : "out");
    } else {
      zoomActions.resetZoom();
    }
  });

  useEffect(() => {
    if (!open) {
      return noCleanup;
    }

    const unregisterOpen = registerOpenImageViewer();

    const unregisterZoom = showZoomControls
      ? registerImageViewerZoomHandler(onHostZoom)
      : undefined;

    return () => {
      unregisterZoom?.();
      unregisterOpen();
    };
  }, [onHostZoom, open, showZoomControls]);

  /** A click on the backdrop, outside every control and the picture. */
  const isBackdropClick = (event: {
    clientX: number;
    clientY: number;
    currentTarget: EventTarget & Element;
    target: EventTarget;
  }) => {
    const { target } = event;

    if (
      !(target instanceof Element) ||
      !event.currentTarget.contains(target) ||
      target.closest(CLOSEST_INTERACTIVE) !== null
    ) {
      return false;
    }

    const preview =
      renderPreview === undefined
        ? imageNode(viewportRef)
        : previewNodeRef.current;

    const rect = preview?.getBoundingClientRect();

    return (
      rect === undefined ||
      event.clientX < rect.left ||
      event.clientX > rect.right ||
      event.clientY < rect.top ||
      event.clientY > rect.bottom
    );
  };

  const closeOnBackdrop = (event: ReactPointerEvent<HTMLDivElement>) => {
    if (!inline && !overlay && event.target === event.currentTarget) {
      changeOpen(false);
    }
  };

  const downloadButtonClass = cn(
    CONTROL_SURFACE,
    controlsSurface === "opaque" ? "bg-panel-tertiary" : "bg-panel-tertiary/95",
    "h-10 min-w-10 px-3"
  );

  const roundSurface = cn(
    controlsSurface === "opaque" ? "bg-panel-tertiary" : "bg-panel-tertiary/95"
  );

  const trimmed = caption?.trim();

  const trimmedCaption =
    trimmed === undefined || trimmed === "" ? null : trimmed;

  const linkDownload = /^https?:/iu.test(surface);

  const download = showDownload ? (
    <DownloadControl
      alt={alt}
      ariaLabel={downloadAriaLabel}
      className={downloadButtonClass}
      downloadSrc={surface}
      fileName={downloadFileName}
      host={host}
      isLink={linkDownload}
      onDownload={onDownload}
      onDownloadClick={onDownloadClick}
      onDownloaded={onDownloaded}
      onDownloadFailure={onDownloadFailure}
      previewImage={() => imageNode(viewportRef)}
      swallowPointer={swallowPointer}
      src={src}
    />
  ) : null;

  const zoomControlsBottom = showZoomControls;

  const bottomVisible =
    !inline ||
    bottomContent !== undefined ||
    trimmedCaption !== null ||
    renderBottomAction !== undefined ||
    zoomControlsBottom;

  const preview =
    previewContent ??
    renderPreview?.({
      imageRef: (element) => {
        previewNodeRef.current = element;
      },
    }) ??
    (zoomableContent === undefined ? (
      // oxlint-disable-next-line nextjs/no-img-element -- the viewer shows an arbitrary photo at its natural size and zooms it by sizing the element.
      <img
        alt={alt}
        className={cn(
          "m-auto object-contain",
          imageDisplaySize !== undefined &&
            contentSize === undefined &&
            "invisible",
          imageSurface === "card" ? "shrink-0" : "rounded-lg",
          imageSurface === "card" &&
            contentSize !== undefined &&
            "max-h-none! max-w-none!",
          contentSize === undefined
            ? "max-h-full max-w-full"
            : "block h-(--ck-viewer-image-height) w-(--ck-viewer-image-width) max-w-none"
        )}
        decoding={imageDecoding}
        draggable={imageDraggable}
        fetchPriority={imageFetchPriority}
        height={imageDisplaySize?.height}
        key={src}
        loading={imageLoading}
        onError={onImageError}
        onLoad={(event) => {
          zoomActions.readNaturalSize(event.currentTarget);
          onImageLoad?.(event);
        }}
        onPointerDown={(event) => {
          event.stopPropagation();
        }}
        // A stable ref callback: a new function each render would run decode again each render.
        // oxlint-disable-next-line react/refs
        ref={zoomActions.attachImage}
        referrerPolicy={imageReferrerPolicy}
        src={src}
        style={contentSize}
        width={imageDisplaySize?.width}
      />
    ) : (
      <div
        className={cn(
          "m-auto shrink-0 select-text",
          contentSize !== undefined &&
            "h-(--ck-viewer-image-height) w-(--ck-viewer-image-width)"
        )}
        onPointerDown={(event) => {
          event.stopPropagation();
        }}
        ref={zoomActions.attachContent}
        style={contentSize}
      >
        {zoomableContent.content}
      </div>
    ));

  const gestures = previewContent === undefined && renderPreview === undefined;

  const frame = (
    <FrameElement
      className={cn(
        "pointer-events-auto flex flex-col justify-center",
        overlay ? "items-stretch" : "items-center",
        contained && containerResizeEdges === "all" && "absolute inset-2",
        contained &&
          containerResizeEdges === "top-and-sides" &&
          "absolute inset-x-2 top-2 bottom-0",
        !(contained && containerResizeEdges !== undefined) &&
          "relative size-full",
        !overlay && "pb-8",
        !(inline || overlay) && contained && "pt-12",
        !(inline || overlay || contained) &&
          "in-data-[ui-titlebar-inset]:pt-24",
        !(inline || overlay) &&
          (hasNavigation ? "px-16 sm:px-20" : "px-4 sm:px-8")
      )}
      onPointerDown={closeOnBackdrop}
      plain={inline || contained || overlay}
      windowControlsRight={windowControls.right}
    >
      {headerContent}
      {inline || overlay ? null : (
        <div
          className={cn(
            "absolute right-3 z-10 flex items-center gap-2",
            contained
              ? "top-3"
              : cn(styles.windowActions, "in-data-[ui-titlebar-inset]:top-12")
          )}
        >
          {toolbarLeadingAction === undefined ? null : (
            <Button
              aria-label={toolbarLeadingAction.ariaLabel}
              aria-pressed={toolbarLeadingAction.active}
              className={cn(
                downloadButtonClass,
                "relative",
                toolbarLeadingAction.active === true
                  ? "h-9 min-w-0 p-1"
                  : "h-9 min-w-10 px-3"
              )}
              disabledAppearance="none"
              focusRing="none"
              onClick={(event) => {
                event.stopPropagation();
                toolbarLeadingAction.onClick();
              }}
              onPointerDown={swallowPointer}
              unstyled
            >
              <span
                className={cn(
                  "pointer-events-none rounded-full text-sm font-medium whitespace-nowrap",
                  toolbarLeadingAction.active === true &&
                    "bg-text-notice px-3 py-1 text-white",
                  toolbarLeadingAction.active !== true && "p-1"
                )}
              >
                {toolbarLeadingAction.label}
              </span>
            </Button>
          )}
          {editButton === undefined ? null : (
            <Button
              aria-label={editButton.ariaLabel}
              className={downloadButtonClass}
              disabledAppearance="none"
              focusRing="none"
              onClick={(event) => {
                event.stopPropagation();
                editButton.onClick();
              }}
              onPointerDown={swallowPointer}
              unstyled
            >
              {editButton.icon}
            </Button>
          )}
          {download}
          {toolbarContent}
          {toolbarActions?.map((action) => (
            <Button
              aria-label={action.ariaLabel}
              className={downloadButtonClass}
              disabledAppearance="none"
              focusRing="none"
              key={action.ariaLabel}
              onClick={(event) => {
                event.stopPropagation();
                action.onClick();
              }}
              onPointerDown={swallowPointer}
              unstyled
            >
              {action.icon}
            </Button>
          ))}
          <Button
            aria-label={closeAriaLabel}
            className={downloadButtonClass}
            disabledAppearance="none"
            focusRing="none"
            onClick={(event) => {
              event.stopPropagation();
              changeOpen(false);
            }}
            onPointerDown={swallowPointer}
            unstyled
          >
            <ViewerCloseIcon className="size-4.5" />
          </Button>
        </div>
      )}
      {onPreviousImage === undefined ? null : (
        <Button
          aria-label={previousAriaLabel}
          className={cn(
            downloadButtonClass,
            "absolute top-1/2 left-3 z-10 -translate-y-1/2 p-0"
          )}
          disabled={previousDisabled}
          disabledAppearance="none"
          focusRing="none"
          onClick={(event) => {
            event.stopPropagation();
            showPrevious();
          }}
          onPointerDown={(event) => {
            event.stopPropagation();
          }}
          unstyled
        >
          <ViewerArrowLeftIcon className="size-4.5" />
        </Button>
      )}
      {onNextImage === undefined ? null : (
        <Button
          aria-label={nextAriaLabel}
          className={cn(
            downloadButtonClass,
            "absolute top-1/2 right-3 z-10 -translate-y-1/2 p-0"
          )}
          disabled={nextDisabled}
          disabledAppearance="none"
          focusRing="none"
          onClick={(event) => {
            event.stopPropagation();
            showNext();
          }}
          onPointerDown={(event) => {
            event.stopPropagation();
          }}
          unstyled
        >
          <ViewerArrowLeftIcon className="size-4.5 rotate-180" />
        </Button>
      )}
      <div
        className={cn(
          imageSurface === "card" &&
            "flex min-h-0 w-full flex-1 overflow-hidden rounded-2xl bg-panel-elevated-secondary p-4",
          imageSurface !== "card" &&
            (overlay ? "flex min-h-0 w-full flex-1 px-18" : "contents")
        )}
      >
        <div
          className={cn(
            "flex min-h-0 w-full min-w-0 flex-1 items-start justify-start overflow-auto",
            overlay && "relative items-stretch self-stretch overflow-hidden",
            previewContent === undefined && "touch-none"
          )}
          data-testid="image-viewer-dismiss-region"
          onPointerCancelCapture={gestures ? touch.onPointerUp : undefined}
          onPointerDown={(event) => {
            if (
              !inline &&
              !overlay &&
              imageSurface !== "card" &&
              event.target === event.currentTarget
            ) {
              changeOpen(false);
            }
          }}
          onPointerDownCapture={gestures ? touch.onPointerDown : undefined}
          onPointerMoveCapture={gestures ? touch.onPointerMove : undefined}
          onPointerUpCapture={gestures ? touch.onPointerUp : undefined}
          ref={zoomActions.attachViewport}
        >
          {inline ? null : (
            <DialogTitle className="sr-only">{dialogAriaLabel}</DialogTitle>
          )}
          {preview}
        </div>
      </div>
      {bottomVisible ? (
        <div
          className={
            overlay
              ? "z-10 flex min-w-0 shrink-0 items-center justify-center gap-3 p-4 text-sm"
              : "z-10 mt-5 flex max-w-[min(48rem,calc(100vw-2rem))] flex-col items-center gap-3 text-text"
          }
        >
          {renderBottomAction?.(
            cn(
              CONTROL_SURFACE,
              roundSurface,
              "gap-1 px-4 py-2 text-sm no-underline"
            )
          )}
          {bottomContent}
          {trimmedCaption === null ? null : (
            <div
              className={cn(
                roundSurface,
                "max-w-full rounded-2xl px-4 py-2 text-center text-sm shadow-md ring-1 ring-black/5"
              )}
            >
              {trimmedCaption}
            </div>
          )}
          {zoomControlsBottom ? (
            <div
              className={cn(
                roundSurface,
                "flex items-center gap-1 rounded-full p-1 shadow-md ring-1 ring-black/5"
              )}
            >
              <Button
                aria-label="Zoom out image"
                className={ZOOM_BUTTON_CLASS}
                disabled={!zoomView.canZoomOut}
                disabledAppearance="none"
                focusRing="none"
                onClick={() => {
                  zoomActions.step("out");
                }}
                unstyled
              >
                <ViewerMinusIcon className="size-3.5" />
              </Button>
              <div className="flex min-w-16 items-center justify-center px-2 text-center text-sm tabular-nums [-webkit-app-region:no-drag]">
                <span>{percentLabel}</span>
              </div>
              <Button
                aria-label="Zoom in image"
                className={ZOOM_BUTTON_CLASS}
                disabled={!zoomView.canZoomIn}
                disabledAppearance="none"
                focusRing="none"
                onClick={() => {
                  zoomActions.step("in");
                }}
                unstyled
              >
                <ViewerPlusIcon className="size-3.5" />
              </Button>
            </div>
          ) : null}
        </div>
      ) : null}
    </FrameElement>
  );

  if (inline) {
    return frame;
  }

  return (
    <Dialog
      contentClassName={
        overlay
          ? undefined
          : cn(
              CLASSIC_CONTENT_CLASS,
              contained ? "h-full w-full" : "fixed h-[100dvh] w-screen",
              (contained || !modal) && "!bg-black/90",
              disableOpenAnimation && "!animate-none"
            )
      }
      contentProps={{
        "aria-describedby": undefined,
        "aria-label": dialogAriaLabel,
        onAuxClick: (event) => {
          event.stopPropagation();
        },
        onClick: (event) => {
          event.stopPropagation();

          if (overlay) {
            const pressed = clickStartRef.current !== null;
            clickStartRef.current = null;

            if (
              pressed &&
              event.detail > 0 &&
              !event.defaultPrevented &&
              isBackdropClick(event)
            ) {
              changeOpen(false);
            }
          } else if (event.target === event.currentTarget) {
            changeOpen(false);
          }
        },
        onCloseAutoFocus,
        onEscapeKeyDown: (event) => {
          if (event.composedPath()[0] instanceof HTMLInputElement) {
            event.preventDefault();
          } else {
            event.stopPropagation();
          }
        },
        onInteractOutside:
          contained || !modal
            ? (event) => {
                event.preventDefault();
              }
            : undefined,
        onKeyDown: (event) => {
          const modified =
            event.defaultPrevented ||
            event.altKey ||
            event.ctrlKey ||
            event.metaKey ||
            event.shiftKey ||
            event.nativeEvent.isComposing;

          if (modified || !allowsArrowNavigation(event.target)) {
            return;
          }

          if (event.key === "ArrowLeft" && onPreviousImage !== undefined) {
            event.preventDefault();
            event.stopPropagation();
            showPrevious();
          }

          if (event.key === "ArrowRight" && onNextImage !== undefined) {
            event.preventDefault();
            event.stopPropagation();
            showNext();
          }
        },
        onOpenAutoFocus,
        onPointerCancelCapture: overlay
          ? () => {
              clickStartRef.current = null;
            }
          : undefined,
        onPointerDownCapture: overlay
          ? (event) => {
              clickStartRef.current =
                event.isPrimary && event.button === 0 && isBackdropClick(event)
                  ? pointOf(event)
                  : null;
            }
          : undefined,
        onPointerMoveCapture: overlay
          ? (event) => {
              const start = clickStartRef.current;

              if (
                start !== null &&
                Math.hypot(
                  event.clientX - start.clientX,
                  event.clientY - start.clientY
                ) > CLICK_SLOP_PX
              ) {
                clickStartRef.current = null;
              }
            }
          : undefined,
      }}
      modal={modal && !contained}
      onOpenChange={changeOpen}
      open={open}
      overlayClassName={
        overlay
          ? undefined
          : cn(
              "!bg-black/90",
              contained &&
                containerResizeEdges !== undefined &&
                "pointer-events-none",
              disableOpenAnimation && "!animate-none"
            )
      }
      portalContainer={container}
      showDialogClose={false}
      triggerContent={triggerContent}
      unstyledContent={!overlay}
      variant={overlay ? "image" : undefined}
      viewportSized={!contained}
    >
      {frame}
    </Dialog>
  );
};

"use client";

import { useSyncExternalStore } from "react";

/*
 * The host zoom bridge. The desktop
 * menu cannot reach into a viewer, so the viewer registers with this module
 * while it is open: the host menu calls `dispatchImageViewerZoom`, and the
 * rest of the app asks `isImageViewerActive` to know a viewer is showing.
 */

export type ImageViewerZoomCommand =
  | { delta: number; type: "step-zoom" }
  | { type: "reset-zoom" };

type ZoomHandler = (command: ImageViewerZoomCommand) => void;

let openViewerCount = 0;
let zoomHandler: ZoomHandler | null = null;
const activeListeners = new Set<() => void>();

const notifyActive = () => {
  for (const listener of activeListeners) {
    listener();
  }
};

/** Listens for the active state changing; returns the unsubscribe. */
export const subscribeImageViewerActive = (listener: () => void) => {
  activeListeners.add(listener);

  return () => {
    activeListeners.delete(listener);
  };
};

/** Is any viewer open? */
export const isImageViewerActive = () => openViewerCount > 0;

/**
 * Counts an open viewer. The returned cleanup counts it out once,
 * however many times it is called, and the count never goes below zero.
 */
export const registerOpenImageViewer = () => {
  let registered = true;
  openViewerCount += 1;
  notifyActive();

  return () => {
    if (registered) {
      registered = false;
      openViewerCount = Math.max(0, openViewerCount - 1);
      notifyActive();
    }
  };
};

/**
 * Makes `handler` the one that receives zoom commands. A later
 * registration replaces it, and a cleanup only clears the handler it set.
 */
export const registerImageViewerZoomHandler = (handler: ZoomHandler) => {
  zoomHandler = handler;

  return () => {
    if (zoomHandler === handler) {
      zoomHandler = null;
    }
  };
};

/** The host menu sends a zoom command to the registered viewer. */
export const dispatchImageViewerZoom = (command: ImageViewerZoomCommand) => {
  zoomHandler?.(command);
};

/** Whether a viewer is open, as React state. */
export const useImageViewerActive = () =>
  useSyncExternalStore(
    subscribeImageViewerActive,
    isImageViewerActive,
    () => false
  );

/*
 * The image placeholder of the photo carousel. Tailwind cannot define
 * @keyframes, so this module draws a tinted
 * fill (--color-description is --ck-palette-ink-tertiary in
 * the app theme, 8% in light and 12% in dark) that pulses between .68 and .82
 * opacity over 2.4s, and holds at .76 when :root has data-ck-reduced-motion="true".
 * The .dark rule is the nearest theme scope here, through light-dark.
 */

@keyframes pulse {
  0%,
  to {
    opacity: 0.68;
  }

  50% {
    opacity: 0.82;
  }
}

.placeholder {
  background-color: light-dark(
    color-mix(
      in srgb,
      var(--ck-palette-ink-tertiary) 8%,
      var(--ck-palette-surface-surface)
    ),
    color-mix(
      in srgb,
      var(--ck-palette-ink-tertiary) 12%,
      var(--ck-palette-surface-surface)
    )
  );
  opacity: 0.68;
  animation: 2.4s ease-in-out infinite pulse;
}

:global(:root[data-ck-reduced-motion="true"]) .placeholder {
  opacity: 0.76;
  animation: none;
}

/*
 * Window content and window actions:
 * the viewer frame leaves room for the window title bar. Every selector is in
 * :where, and the rules sit in the components layer, so any padding or top
 * utility on the element wins. The frame sets --window-titlebar-height to
 * env(titlebar-area-height, 0px); a CSS module would rename that name inside
 * env.
 */
@layer components {
  :where(.windowContent) {
    padding-top: calc(var(--spacing) * 12);
  }

  :where(.windowActions) {
    top: calc(var(--spacing) * 3);
  }

  :where(.windowContent[data-ck-right-window-controls="true"]):not(
    :where(:global(.compact-window) *)
  ) {
    padding-top: calc(
      var(--window-titlebar-height) / var(--ui-display-scale) + var(--spacing) *
        16
    );
  }

  :where(.windowContent[data-ck-right-window-controls="true"]):not(
      :where(:global(.compact-window) *)
    )
    > :where(.windowActions) {
    top: calc(
      var(--window-titlebar-height) / var(--ui-display-scale) + var(--spacing) *
        3
    );
  }
}

"use client";

/* oxlint-disable react/no-react-children, shadcn/no-restyle -- The carousel counts children and uses unstyled buttons for dots and photo slides. */

import {
  ChevronLeft20Icon,
  ChevronRightGallery16Icon,
  ChevronRight16Icon,
  ChevronRight20Icon,
} from "@/components/carousel/icons";
import { useGeneratedImageSource } from "@/components/carousel/image-source";
import type { ImageAssetResolver } from "@/components/carousel/image-source";
import { ImageViewerDialog } from "@/components/carousel/image-viewer";
import { Button } from "@/components/ui/button";
import type { LayerEvent } from "@/lib/dismissable-layer";
import { cn } from "@/lib/utils";
import {
  Children,
  createContext,
  useCallback,
  useContext,
  useImperativeHandle,
  useInsertionEffect,
  useLayoutEffect,
  useRef,
  useState,
} from "react";
import type {
  CSSProperties,
  KeyboardEvent,
  ReactNode,
  Ref,
  UIEvent,
} from "react";

import styles from "./carousel.module.css";

type ScrollDirection = "ltr" | "rtl";

const HIDE_SCROLLBAR =
  "[-ms-overflow-style:none] [scrollbar-width:none] [&::-webkit-scrollbar]:hidden";

/** The reduced-motion variant is the root attribute, else the media query. */
const NO_SMOOTH_SCROLL =
  "[:root[data-ck-reduced-motion=true]_&]:scroll-auto motion-reduce:[:root:not([data-ck-reduced-motion])_&]:scroll-auto";

const NO_TRANSITION =
  "[:root[data-ck-reduced-motion=true]_&]:transition-none motion-reduce:[:root:not([data-ck-reduced-motion])_&]:transition-none";

/** An effect or ref cleanup for the paths that set nothing up. */
const noCleanup = () => {
  // Nothing was set up, so there is nothing to undo.
};

const clampBetween = (value: number, lower: number, upper: number) =>
  Math.min(upper, Math.max(lower, value));

/* ------------------------------------------------------- scroll targets --- */

const scrollPaddingStart = (
  element: HTMLElement,
  direction: ScrollDirection
) => {
  const style = getComputedStyle(element);

  // The computed scroll padding is a length such as "16px": Number("16px") is NaN, parseFloat reads it.
  // oxlint-disable-next-line unicorn/prefer-number-coercion
  const padding = Number.parseFloat(
    direction === "rtl" ? style.scrollPaddingRight : style.scrollPaddingLeft
  );

  return Number.isNaN(padding) ? 0 : padding;
};

/** Where a child starts, as a scrollLeft. */
const childScrollStart = (
  element: HTMLElement,
  child: HTMLElement,
  direction: ScrollDirection
) =>
  direction === "rtl"
    ? child.offsetLeft -
      element.offsetLeft +
      child.offsetWidth -
      element.clientWidth +
      scrollPaddingStart(element, direction)
    : child.offsetLeft -
      element.offsetLeft -
      scrollPaddingStart(element, direction);

/** The smallest and largest scrollLeft. */
const carouselScrollBounds = (
  element: HTMLElement,
  direction: ScrollDirection = "ltr"
) => {
  const range = Math.max(0, element.scrollWidth - element.clientWidth);

  if (direction === "rtl") {
    return { maximum: 0, minimum: -range };
  }

  const first = element.firstElementChild;

  return {
    maximum: range,
    minimum: Math.min(
      range,
      first instanceof HTMLElement
        ? Math.max(0, childScrollStart(element, first, direction))
        : 0
    ),
  };
};

/**
 * The scrollLeft an arrow press scrolls to.
 * It aims one viewport (less the scroll padding) ahead, then snaps to the
 * first child start at or beyond that point.
 */
const carouselScrollTarget = (
  element: HTMLElement,
  step: -1 | 1,
  direction: ScrollDirection = "ltr"
) => {
  const { maximum, minimum } = carouselScrollBounds(element, direction);
  const physical = direction === "rtl" ? -step : step;

  const aim = clampBetween(
    element.scrollLeft +
      physical * (element.clientWidth - scrollPaddingStart(element, direction)),
    minimum,
    maximum
  );

  const { children } = element;

  for (
    let index = step === 1 ? 0 : children.length - 1;
    index >= 0 && index < children.length;
    index += step
  ) {
    const child = children.item(index);

    if (!(child instanceof HTMLElement)) {
      continue;
    }

    const start = clampBetween(
      childScrollStart(element, child, direction),
      minimum,
      maximum
    );

    if (
      (physical === 1 && start >= aim - 1) ||
      (physical === -1 && start <= aim + 1)
    ) {
      return start;
    }
  }

  return physical === 1 ? maximum : minimum;
};

/* ----------------------------------------------------------- useCarousel --- */

interface CarouselModel {
  canNext: boolean;
  canPrevious: boolean;
}

/** Viewport scroll share of one press of previous or next. */
const SCROLL_SHARE = 0.85;

/**
 * The scroll state of a viewport and the actions
 * that move it. `viewportRef` is a state setter, so it takes the element.
 */
export const useCarousel = () => {
  const [viewport, setViewport] = useState<HTMLElement | null>(null);

  const [model, setModel] = useState<CarouselModel>({
    canNext: false,
    canPrevious: false,
  });

  useLayoutEffect(() => {
    if (viewport === null) {
      return noCleanup;
    }

    const refresh = () => {
      const range = Math.max(0, viewport.scrollWidth - viewport.clientWidth);
      const offset = Math.min(range, Math.abs(viewport.scrollLeft));
      const canPrevious = offset > 1;
      const canNext = offset < range - 1;

      setModel((current) =>
        current.canPrevious === canPrevious && current.canNext === canNext
          ? current
          : { canNext, canPrevious }
      );
    };

    refresh();
    viewport.addEventListener("scroll", refresh, { passive: true });

    const resizeObserver = new ResizeObserver(refresh);

    const observeChildren = () => {
      resizeObserver.disconnect();
      resizeObserver.observe(viewport);

      for (const child of viewport.children) {
        resizeObserver.observe(child);
      }

      refresh();
    };

    const mutationObserver = new MutationObserver(observeChildren);
    mutationObserver.observe(viewport, { childList: true });
    observeChildren();

    return () => {
      viewport.removeEventListener("scroll", refresh);
      resizeObserver.disconnect();
      mutationObserver.disconnect();
    };
  }, [viewport]);

  const scroll = useCallback(
    (step: -1 | 1) => {
      if (viewport === null) {
        return;
      }

      const view = viewport.ownerDocument.defaultView;
      const rtl = view?.getComputedStyle(viewport).direction === "rtl";

      const reduceMotion =
        view?.matchMedia("(prefers-reduced-motion: reduce)").matches === true;

      viewport.scrollBy({
        behavior: reduceMotion ? "instant" : "smooth",
        left: step * (rtl ? -1 : 1) * viewport.clientWidth * SCROLL_SHARE,
      });
    },
    [viewport]
  );

  return {
    actions: {
      next: () => {
        scroll(1);
      },
      previous: () => {
        scroll(-1);
      },
      viewportRef: setViewport,
    },
    model,
  };
};

